 "content": "def transform(grid):
    from collections import Counter
    out = [row[:] for row in grid]
    # Full-width monochrome rows reveal the two colors involved. The less
    # frequent solid-row color is the foreground; fill the complementary
    # section of its partial row with color 1.
    counts = Counter(row[0] for row in grid if row and len(set(row)) == 1)
    for r, row in enumerate(grid):
        if len(set(row)) <= 1:
            continue
        candidates = [c for c in set(row) if c in counts]
        if len(candidates) == 2:
            color = min(candidates, key=lambda c: counts[c])
            for j, value in enumerate(row):
                if value != color:
                    out[r][j] = 1
    return out
